function dealerExchangeMaybeListVehicle(exchange,dealer){
  const strategy=dealer.strategy,candidates=exchange.inventoryVehicles.filter(v=>v.ownerDealerId===dealer.id&&!v.listed&&!v.auctionId&&exchange.simulationTick-(v.lastWithdrawnTick||0)>=2);
  const ranked=candidates.map(v=>{const held=Math.max(0,exchange.simulationTick-(v.acquiredAtTick||0)),fit=(strategy.preferredBrands.includes(v.brand)?1:0)+(strategy.vehicleTypes.includes(v.segment)?1:0),pressure=dealer.inventoryCount/dealer.inventoryCapacity;const targetMargin=strategy.profitTarget/100;const desired=Math.round(Math.max(v.marketValue*(.96+Math.min(.08,v.demand/1000)),(v.acquisitionCost||0)*(1+targetMargin)));const score=held*3+pressure*30+(fit?0:24)+(v.demand*.12);return{v,held,fit,desired,score};}).sort((a,b)=>b.score-a.score);
  const choice=ranked[0];if(!choice||choice.held<2||choice.score<43)return false;const v=choice.v;v.listed=true;v.dealerId=dealer.id;v.askingPrice=choice.desired;v.interest=0;v.opportunity=Math.round(Math.max(45,Math.min(98,60+(v.marketValue-v.askingPrice)/v.marketValue*100+v.demand*.25)));v.status='active';v.listedAtTick=exchange.simulationTick;v.expiresAtTick=exchange.simulationTick+Math.max(4,strategy.patience);v.expiresIn=`${Math.max(1,strategy.patience)} Handelstage`;exchange.vehicles.push({...v});exchange.scheduler.totalListings++;
  dealerExchangeRecordHistory(exchange,dealer.id,{type:'listing',vehicleId:v.id,title:'Fahrzeug eingestellt',detail:`${v.brand} ${v.model} · ${v.askingPrice.toLocaleString('de-DE')} €`});dealerExchangeAddEvent(exchange,{type:'listing',dealerId:dealer.id,vehicleId:v.id,title:'Neues Händlerangebot',text:`${dealer.companyName} stellt einen ${v.brand} ${v.model} für ${v.askingPrice.toLocaleString('de-DE')} € ein.`});return true;
}
function dealerExchangeEvaluateDealer(exchange,dealer,playerContext){
  const candidates=exchange.vehicles.filter(v=>v.dealerId!==dealer.id&&v.status==='active').map(v=>({v,result:dealerExchangeEconomicScore(dealer,v)})).sort((a,b)=>b.result.score-a.result.score).slice(0,DEALER_EXCHANGE_CANDIDATES_PER_DEALER);
  for(const item of candidates){const playerListing=item.v.dealerId==='player',action=!item.result.budgetOk?'ignore':item.result.score>=item.result.threshold?'buy':item.result.score>=item.result.threshold-16?'observe':'ignore';dealerExchangeRecordDecision(exchange,dealer,item.v,item.result,action);if(playerListing&&action!=='ignore'){if(dealerExchangeMaybeCreateDirectOffer(exchange,dealer,item.v,item.result))break;}else if(action==='buy'&&dealerExchangeReserveVehicle(exchange,dealer,item.v,item.result,playerContext))break;}
  dealerExchangeMaybeListVehicle(exchange,dealer);
}
function runDealerExchangeCycle(exchange,now=Date.now(),playerContext=null){
  ensureDealerExchangePhase2(exchange,now);exchange.simulationTick++;dealerExchangeProcessPending(exchange,playerContext);dealerExchangeProcessPhase5(exchange,playerContext);dealerExchangeMaybeStartAuction(exchange);const count=Math.min(DEALER_EXCHANGE_DEALERS_PER_CYCLE,exchange.dealers.length);
  for(let i=0;i<count;i++){const index=(exchange.scheduler.cursor+i)%exchange.dealers.length;dealerExchangeEvaluateDealer(exchange,exchange.dealers[index],playerContext);}
  exchange.scheduler.cursor=(exchange.scheduler.cursor+count)%exchange.dealers.length;exchange.scheduler.lastRunAt=now;exchange.scheduler.nextRunAt=now+DEALER_EXCHANGE_ENGINE_INTERVAL_MS;return true;
}
function dealerExchangePlayerPurchase(exchange,playerState,listingId,playerName){
  ensureDealerExchangePhase2(exchange);const listing=exchange.vehicles.find(v=>v.id===listingId),seller=listing&&exchange.dealers.find(d=>d.id===listing.dealerId);if(!listing||!seller||listing.status!=='active')return{ok:false,reason:'unavailable'};if((playerState.cash||0)<listing.askingPrice)return{ok:false,reason:'funds'};const owned=exchange.inventoryVehicles.find(v=>v.id===listing.id&&v.ownerDealerId===seller.id);if(!owned)return{ok:false,reason:'ownership'};
  const sellerProfit=listing.askingPrice-(owned.acquisitionCost||listing.askingPrice);playerState.cash-=listing.askingPrice;seller.cashBalance+=listing.askingPrice;seller.inventoryCount=Math.max(0,seller.inventoryCount-1);seller.tradeCount++;seller.realizedProfit+=sellerProfit;seller.inventoryVehicleIds=seller.inventoryVehicleIds.filter(id=>id!==owned.id);owned.ownerDealerId='player';owned.dealerId='player';owned.acquisitionCost=listing.askingPrice;owned.acquiredAtTick=exchange.simulationTick;owned.listed=false;exchange.vehicles=exchange.vehicles.filter(v=>v.id!==listing.id);exchange.observations=exchange.observations.filter(o=>o.vehicleId!==listing.id);
  exchange.transactions.unshift({id:`dxt-${++exchange.nextEntityId}`,tick:exchange.simulationTick,vehicleId:listing.id,buyerDealerId:'player',sellerDealerId:seller.id,price:listing.askingPrice,expectedProfit:listing.marketValue-listing.askingPrice,sellerProfit});exchange.transactions=exchange.transactions.slice(0,100);exchange.scheduler.totalTrades++;dealerExchangeRecordPlayerTrade(exchange,seller.id,'purchase',listing,listing.askingPrice);dealerExchangeAddEvent(exchange,{type:'trade',dealerId:seller.id,vehicleId:listing.id,title:'Spielerkauf abgeschlossen',text:`${playerName||'Spieler-Autohaus'} kauft den ${listing.brand} ${listing.model} von ${seller.companyName} für ${listing.askingPrice.toLocaleString('de-DE')} €.`});return{ok:true,listing:{...listing},seller};
}
function setDealerExchangeDebug(exchange,enabled){ensureDealerExchangePhase2(exchange);exchange.debug.enabled=!!enabled;return exchange.debug.enabled;}
